#!/usr/bin/env python3
import base64, gzip, json, re, subprocess
from pathlib import Path

B64 = """"""

rows = json.loads(gzip.decompress(base64.b64decode(B64)))
assert len(rows) == 865 and not any(r.get("email") for r in rows)
targets = [
    Path("/var/www/lostpet/LostPet_ASPNET/src/LostPet.Web/wwwroot/data/directories/new/goats.json"),
    Path("/var/www/lostpet/app/wwwroot/data/directories/new/goats.json"),
]
for p in targets:
    p.parent.mkdir(parents=True, exist_ok=True)
    p.write_text(json.dumps(rows, separators=(",", ":")), encoding="utf-8")
    print("WROTE", p, p.stat().st_size)

old = '  if (cat && cat !== "services") return;'
new = """  var midName = (params.get("mid") || params.get("fine") || "").trim().toLowerCase();
  var speciesFile = ({
    goats:"goats", sheep:"sheep", pigs:"pigs", cattle:"cattle", poultry:"poultry",
    rabbits:"rabbits", "rabbits (livestock)":"rabbits", bees:"bees", "bees / apiary":"bees",
    camelids:"camelids", alpaca:"camelids", llama:"camelids",
    dogs:"dogs", cats:"cats", horses:"horses", birds:"birds",
    "reptiles & amphibians":"reptiles", "fish & aquatics":"fish",
    "other livestock":"other-livestock"
  })[midName] || "";
  if (!speciesFile && cat === "supplies") speciesFile = /tack|saddl/.test(midName) ? "tack" : (/feed|farm/.test(midName) ? "feed" : "");
  if (cat && cat !== "services" && !speciesFile) return;"""

old2 = """  Promise.all([
    kinds.groom ? load("/data/directories/us-groomers.json") : [],
    kinds.farrier ? load("/data/directories/us-farriers.json") : [],
    kinds.board ? load("/data/directories/us-boarding.json") : [],
    kinds.equine ? load("/data/directories/us-equine-boarding.json") : []
  ]).then(function(parts){
    var rows = [];
    parts.forEach(function(p){ if (p && p.length) rows = rows.concat(p); });
    rows = rows.filter(hit);"""

new2 = """  var loads = speciesFile ? [load("/data/directories/new/" + speciesFile + ".json")] : [
    kinds.groom ? load("/data/directories/us-groomers.json") : [],
    kinds.farrier ? load("/data/directories/us-farriers.json") : [],
    kinds.board ? load("/data/directories/us-boarding.json") : [],
    kinds.equine ? load("/data/directories/us-equine-boarding.json") : []
  ];
  var note = "";
  Promise.all(loads).then(function(parts){
    var all = [];
    parts.forEach(function(p){ if (p && p.length) all = all.concat(p); });
    var rows = all.filter(hit);
    if (!rows.length && zipF) {
      var savedZip = zipF; zipF = "";
      rows = all.filter(hit); zipF = savedZip;
      if (rows.length) note = "None in ZIP " + savedZip + ".";
    }
    if (!rows.length && cityF) {
      var savedCity = cityF; cityF = "";
      rows = all.filter(hit); cityF = savedCity;
      if (rows.length) note = "None in that city.";
    }"""

old3 = 'document.getElementById("lp-count").textContent = "Showing " + shown.toLocaleString() + " of " + rows.length.toLocaleString() + (more ? ". Scroll for more." : ".");'
new3 = 'document.getElementById("lp-count").textContent = (note ? note + " " : "") + "Showing " + shown.toLocaleString() + " of " + rows.length.toLocaleString() + (more ? ". Scroll for more." : ".");'

js_paths = [
    Path("/var/www/lostpet/LostPet_ASPNET/src/LostPet.Web/wwwroot/js/lp-svc-dir.js"),
    Path("/var/www/lostpet/app/wwwroot/js/lp-svc-dir.js"),
]
for jp in js_paths:
    if not jp.exists():
        print("MISSING", jp)
        continue
    t = jp.read_text(encoding="utf-8")
    if "speciesFile" not in t:
        if old not in t or old2 not in t or old3 not in t:
            print("PATTERN MISSING", jp)
            continue
        t = t.replace(old, new, 1).replace(old2, new2, 1).replace(old3, new3, 1)
        jp.write_text(t, encoding="utf-8")
        print("PATCHED", jp)
    else:
        print("JS ALREADY", jp)

src = Path("/var/www/lostpet/LostPet_ASPNET/src/LostPet.Web")
n = 0
for f in list(src.rglob("*.cshtml")) + list(src.rglob("*.js")) + list(src.rglob("*.html")):
    if any(x in f.parts for x in ("bin", "obj")): continue
    try: tx = f.read_text(encoding="utf-8")
    except Exception: continue
    tx2 = re.sub(r"lp-svc-dir\\.js\\?v=\\d+", "lp-svc-dir.js?v=8", tx)
    if tx2 != tx:
        f.write_text(tx2, encoding="utf-8")
        n += 1
        print("VER", f)
print("VER_COUNT", n)
r = subprocess.run(["dotnet", "publish", "-c", "Release", "-o", "/var/www/lostpet/app"], cwd=src, text=True, capture_output=True)
print("PUBLISH_EXIT", r.returncode)
if r.returncode != 0:
    err = (r.stderr or "") + "\\n" + (r.stdout or "")
    print("\\n".join([ln for ln in err.splitlines() if "error" in ln.lower()][-12:]))
else:
    # publish can overwrite the patched published js; copy the patched source again
    src_js = js_paths[0].read_text(encoding="utf-8")
    js_paths[1].write_text(src_js, encoding="utf-8")
    targets[1].write_text(targets[0].read_text(encoding="utf-8"), encoding="utf-8")
subprocess.run(["systemctl", "restart", "lostpet"])
print(subprocess.run(["systemctl", "is-active", "lostpet"], capture_output=True, text=True).stdout.strip())
print("DONE")
